<?php
declare(strict_types=1);
define('NARRRFS_SESSION_READ_ONLY', true);
require_once __DIR__ . '/../../api/config/admin-authorization.php';
narrrfs_require_admin_request('owner_control.lab_store_live_offers.ui.v1');
$draftsAvailable = getenv('NARRRFS_OWNER_LAB_STORE_DRAFTS_UI_ENABLED') === '1' && getenv('NARRRFS_OWNER_LAB_STORE_DRAFTS_READ_ENABLED') === '1';
$historyAvailable = $draftsAvailable && getenv('NARRRFS_OWNER_LAB_STORE_DRAFT_PUBLISH_ENABLED') === '1';
$toggleAvailable = getenv('NARRRFS_OWNER_LAB_STORE_LIVE_OFFERS_TOGGLE_ENABLED') === '1';
$commercialAvailable = getenv('NARRRFS_OWNER_LAB_STORE_LIVE_OFFERS_COMMERCIAL_ENABLED') === '1';
$overviewAvailable = getenv('NARRRFS_OWNER_LAB_STORE_OFFERS_READ_ENABLED') === '1' && getenv('NARRRFS_OWNER_LAB_STORE_OFFERS_UI_ENABLED') === '1';
header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store, max-age=0'); header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: DENY');
if (strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? '')) === 'HEAD') exit;
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Control — Live Lab Store Offers</title>
<style>:root{color-scheme:dark;font-family:system-ui,sans-serif}body{margin:0;background:#111820;color:#f4f7fb;padding:24px}main{max-width:1120px;margin:auto}a{color:#f6cc65}.lede{color:#b8c6d2}.cards{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));margin-top:20px}.card{background:#1b2530;border:1px solid #33404c;border-radius:12px;overflow:hidden}.copy{padding:16px}.card h2{margin:0 0 8px;font-size:1.1rem}.card p{margin:6px 0;color:#b8c6d2}.media{display:block;width:100%;height:170px;object-fit:contain;background:#0d141c}.fallback{display:grid;place-items:center;width:100%;height:170px;background:#0d141c;color:#b8c6d2}#status{min-height:1.5em;padding:12px;border-left:3px solid #f6cc65;background:#18232e}.toggle,#more{padding:9px 14px;margin-top:10px}</style></head>
<body><main><p><a href="/owner-control/v1/index.php">← Owner Control</a></p><nav aria-label="Lab Store"><?php if($overviewAvailable): ?><a href="/owner-control/v1/lab-store-offers.php">Overview</a> · <?php endif; ?><span aria-current="page">Live Offers</span><?php if($draftsAvailable): ?> · <a href="/owner-control/v1/lab-store-drafts.php">Open Draft Workspace — private drafts, not live offers</a><?php endif; ?><?php if($historyAvailable): ?> · <a href="/owner-control/v1/lab-store-drafts.php#history">History</a><?php endif; ?></nav><h1>Live Lab Store Offers</h1><p class="lede">Current shop state. Controls affect only availability, price and stock; purchases and fulfillment remain separate.</p><p id="status" role="status">Loading current offers…</p><section id="cards" class="cards" aria-label="Current Lab Store offers"></section><button id="more" type="button" hidden>Show more</button></main>
<script>
'use strict';
const fields=['offer_id','title','category','source_type','offer_active','source_available','lp_price','dspoinc_price','stock','presentation_ref','media_kind','owner_control_version'];
const cards=document.getElementById('cards'),status=document.getElementById('status'),more=document.getElementById('more'),toggleAvailable=<?= $toggleAvailable ? 'true' : 'false' ?>,commercialAvailable=<?= $commercialAvailable ? 'true' : 'false' ?>;
let cursor=null;
const pendingToggleKeys=new Map();
let activeToggleTarget=null;
function valid(o){return o&&typeof o==='object'&&Object.keys(o).every(k=>fields.includes(k))&&Number.isInteger(o.offer_id)&&Number.isInteger(o.owner_control_version)&&typeof o.title==='string'&&typeof o.offer_active==='boolean'}
function fallback(){const e=document.createElement('p');e.className='fallback';e.textContent='Media unavailable';return e}
function idempotencyKey(){const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
function toggleTargetKey(o,next){return String(o.offer_id)+':'+String(o.owner_control_version)+':'+String(next)}
let pendingCommercial=null;
function commercialKey(payload){const signature=JSON.stringify(payload);if(!pendingCommercial||pendingCommercial.signature!==signature)pendingCommercial={signature,key:idempotencyKey()};return pendingCommercial.key}
function commercialEditor(o){const area=document.createElement('div'),button=document.createElement('button');button.type='button';button.textContent='Edit Price / Stock';button.onclick=()=>{area.replaceChildren();pendingCommercial=null;const form=document.createElement('form');const inputs={};for(const [name,label,value] of [['lp_price','LP price',o.lp_price],['dspoinc_price','DSPOINC price',o.dspoinc_price],['stock','Stock',o.stock]]){const l=document.createElement('label'),input=document.createElement('input');l.textContent=label+' ';input.type='number';input.min=name==='stock'?'0':'1';input.step='1';input.value=value===null?'':String(value);input.setAttribute('aria-label',label);if(name==='stock')input.required=true;inputs[name]=input;l.append(input);form.append(l,document.createElement('br'));input.addEventListener('input',()=>{pendingCommercial=null})}const save=document.createElement('button'),cancel=document.createElement('button');save.type='submit';save.textContent='Save Price / Stock';cancel.type='button';cancel.textContent='Cancel';cancel.onclick=()=>{pendingCommercial=null;area.replaceChildren(button)};form.append(save,cancel);form.onsubmit=async event=>{event.preventDefault();const numberOrNull=input=>input.value===''?null:Number(input.value),payload={offer_id:o.offer_id,expected_version:o.owner_control_version,lp_price:numberOrNull(inputs.lp_price),dspoinc_price:numberOrNull(inputs.dspoinc_price),stock:numberOrNull(inputs.stock)};if(!Number.isSafeInteger(payload.stock)||payload.stock<0||[payload.lp_price,payload.dspoinc_price].some(v=>v!==null&&(!Number.isSafeInteger(v)||v<1))||(payload.lp_price===null&&payload.dspoinc_price===null)){status.textContent='Enter a non-negative stock and at least one positive price.';return}if(!confirm('Save price and stock for this live offer?')){pendingCommercial=null;return}payload.idempotency_key=commercialKey(payload);save.disabled=true;status.textContent='Saving price and stock…';try{const c=await fetch('/api/owner-control/v1/lab-store/live-offer-commercial-csrf.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({action:'edit_commercial'})}),ct=await c.json();if(!c.ok||!ct.success)throw Error();const r=await fetch('/api/owner-control/v1/lab-store/live-offer-commercial.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':ct.csrf_token},credentials:'same-origin',body:JSON.stringify(payload)}),out=await r.json();if(r.status===409&&out.error==='version_conflict'){pendingCommercial=null;status.textContent='Offer changed elsewhere. Reload the offers before saving.';save.disabled=false;return}if(!r.ok||!out.success)throw Error();pendingCommercial=null;cursor=null;await load(false);status.textContent='Price and stock saved.'}catch{save.disabled=false;status.textContent='Save was not confirmed. Retry unchanged values to safely reuse the request key.'}};area.append(form)};area.append(button);return area}
function selectToggleTarget(target){if(activeToggleTarget!==null&&activeToggleTarget!==target)pendingToggleKeys.clear();activeToggleTarget=target}
async function toggleOffer(o,button){const next=!o.offer_active,target=toggleTargetKey(o,next);if(!confirm((next?'Activate':'Disable')+' this existing live offer?')){pendingToggleKeys.delete(target);if(activeToggleTarget===target)activeToggleTarget=null;return}selectToggleTarget(target);const key=pendingToggleKeys.get(target)||idempotencyKey();pendingToggleKeys.set(target,key);button.disabled=true;status.textContent='Saving offer state…';try{const c=await fetch('/api/owner-control/v1/lab-store/live-offer-csrf.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({action:'toggle_active'})}),ct=await c.json();if(!c.ok||!ct.success)throw Error();const r=await fetch('/api/owner-control/v1/lab-store/live-offer-active.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':ct.csrf_token},credentials:'same-origin',body:JSON.stringify({offer_id:o.offer_id,expected_version:o.owner_control_version,is_active:next,idempotency_key:key})}),out=await r.json();if(r.status===409&&(out.error==='version_conflict'||out.error==='state_already_current')){pendingToggleKeys.delete(target);activeToggleTarget=null;status.textContent='Offer state changed elsewhere: reload before retrying.';return}if(!r.ok||!out.success)throw Error();pendingToggleKeys.delete(target);activeToggleTarget=null;status.textContent='Offer state saved.';cursor=null;await load(false)}catch{button.disabled=false;status.textContent='Offer state was not changed. Retry uses the same request key.'}}
function card(o){const e=document.createElement('article'),copy=document.createElement('div'),title=document.createElement('h2'),state=document.createElement('p'),prices=document.createElement('p');e.className='card';copy.className='copy';if(o.presentation_ref){const image=document.createElement('img');image.className='media';image.alt='';image.src=o.presentation_ref;image.addEventListener('error',()=>image.replaceWith(fallback()),{once:true});e.append(image)}else e.append(fallback());title.textContent='#'+o.offer_id+' · '+o.title;state.textContent=o.category+' · '+(o.offer_active?'Active':'Disabled')+' · '+(o.source_available?'Source available':'Source unavailable')+' · Version '+o.owner_control_version;prices.textContent='LP: '+(o.lp_price===null?'Not offered':String(o.lp_price))+' · DSPOINC: '+(o.dspoinc_price===null?'Not offered':String(o.dspoinc_price))+' · Stock: '+String(o.stock);copy.append(title,state,prices);if(toggleAvailable){const b=document.createElement('button');b.type='button';b.className='toggle';b.textContent=o.offer_active?'Disable offer':'Activate offer';b.onclick=()=>toggleOffer(o,b);copy.append(b)}if(commercialAvailable)copy.append(commercialEditor(o));e.append(copy);return e}
async function load(next){try{const url='/api/owner-control/v1/lab-store/live-offers.php?limit=25'+(next&&cursor?'&cursor='+encodeURIComponent(cursor):''),r=await fetch(url,{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p||p.success!==true||p.writes!==false||!p.page||!Array.isArray(p.offers)||!p.offers.every(valid))throw Error();const f=document.createDocumentFragment();p.offers.forEach(o=>f.append(card(o)));if(next)cards.append(f);else cards.replaceChildren(f);cursor=typeof p.page.next_cursor==='string'?p.page.next_cursor:null;more.hidden=cursor===null;status.textContent=p.offers.length?'Current shop state loaded.':'No live offer records are available.'}catch{if(!next)cards.replaceChildren();more.hidden=true;status.textContent='Live offer presentation is currently unavailable.'}}
more.onclick=()=>load(true);load(false);
</script></body></html>
